def to_binary(n):
    if n == 0:
        return "0"
    bits = ""
    while n > 0:
        bits = str(n % 2) + bits   # the remainder is the next bit from the right
        n = n // 2
    return bits


def to_decimal(bits):
    total = 0
    for b in bits:
        total = total * 2 + int(b)
    return total


for n in [5, 13, 42, 255]:
    print(f"{n} -> {to_binary(n)}   (Python: {bin(n)})")

for bits in ["1101", "101010", "11111111"]:
    print(f"{bits} -> {to_decimal(bits)}   (Python: {int(bits, 2)})")

print("0b1101 in code is just", 0b1101)
print("42 as a byte:", format(42, "08b"))
ok = all(to_decimal(to_binary(n)) == n and to_binary(n) == bin(n)[2:] for n in range(256))
print("matches Python for 0-255:", ok)

